def solve(intervals):
    """Merge overlapping or adjacent intervals.
    Gracefully handles malformed inner entries by ignoring them.
    """
    if not intervals:
        return []
    # Filter valid intervals: must be iterable of length 2 with comparable elements
    valid = []
    for iv in intervals:
        try:
            start, end = iv[0], iv[1]
        except Exception:
            continue
        # Ensure start <= end if possible; otherwise swap
        try:
            if start > end:
                start, end = end, start
        except Exception:
            continue
        valid.append([start, end])
    if not valid:
        return []
    # Sort by start
    valid.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = valid[0]
    for start, end in valid[1:]:
        if start <= cur_end:  # overlap or touch
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

