    Handles empty input and ensures integer truncating division toward zero.
    """
    if not tokens:
        return 0
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            if len(stack) < 2:
                # Invalid expression; return 0 as fallback
                return 0
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # Convert to int, ignoring surrounding whitespace
            try:
