    # Guard against invalid or non-iterable inputs.
    if nums is None:
        return []
    if not isinstance(nums, (list, tuple)):
        try:
            nums = list(nums)
        except Exception:
            return []
    # Work on a copy to avoid mutating the original input.
    a = list(nums)
    n = len(a)
    if n <= 1:
        return a
    # Find the first index i from the right where a[i] < a[i+1]
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i == -1:
        # Already the highest permutation: return the smallest (sorted) permutation.
        return sorted(a)
    # Find the smallest element greater than a[i] to the right.
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    # Swap pivot with successor.
    a[i], a[j] = a[j], a[i]
    # Reverse suffix.
    a[i + 1:] = reversed(a[i + 1:])
    return a
