    """Evaluate a Reverse Polish Notation expression.
    Tokens are strings representing integers or the operators '+', '-', '*', '/'.
    Division truncates toward zero (as in the classic LeetCode problem).
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Use absolute division to avoid float inaccuracies and ensure truncation toward zero
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a * b) < 0 else 1
                stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0"}

